import os,glob,re
def load():
    d=os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}
    sessions_g = [p for p in glob.glob(os.path.join(d, '../**/*.jsonl'), recursive=True) if '.jsonl' in p]
    best = None
    for s in sessions_g:
        try:
            name = os.path.basename(s)
            f = open(s)
            txt = f.read().replace('\\n','\n')
            f.close()
            # Check for demo/test patterns
            if re.search(r'Demo pair|Test input', txt):
                if best is None or len(txt) > len(open(best).read()):
                    best = s
        except:
            pass
    if best:
        t=open(best).read().replace('\\n','\n'); G={}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
            k,h,w=m[1],int(m[2]),int(m[3])
            rows=[r.split() for r in t[m.end():].split('\n')[:h]]
            if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
                G[k]=[[int(x) for x in r] for r in rows]
        return G
    return {}
G=load()
print("Loaded grids:", sorted(G.keys()))

